.darma-loader-darma-b16-canal-lock-fill { --accent: var(--loader-color, #0f766e); --accent-2: var(--loader-secondary-color, #5eead4); width: var(--loader-size, 126px); height: calc(var(--loader-size, 126px) * .66); position: relative; }
.darma-loader-darma-b16-canal-lock-fill .darma-loader-darma-b16-canal-lock-fill__chamber { position: absolute; left: 12%; right: 12%; top: 6%; bottom: 6%; overflow: hidden; border-radius: 4px; background: color-mix(in srgb, var(--accent) 10%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 30%, transparent); }
.darma-loader-darma-b16-canal-lock-fill .darma-loader-darma-b16-canal-lock-fill__water { position: absolute; left: 0; right: 0; bottom: 0; height: 16%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b16-canal-lock-fill-lock-fill calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
.darma-loader-darma-b16-canal-lock-fill .darma-loader-darma-b16-canal-lock-fill__boat { position: absolute; left: 32%; bottom: 12%; width: 36%; height: 16%; border-radius: 30% 30% 46% 46% / 20% 20% 90% 90%; background: linear-gradient(color-mix(in srgb, #fff 30%, var(--accent)), var(--accent)); animation: darma-loader-darma-b16-canal-lock-fill-lock-lift calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
.darma-loader-darma-b16-canal-lock-fill .darma-loader-darma-b16-canal-lock-fill__boat::after { content: ''; position: absolute; left: 44%; bottom: 80%; width: 8%; height: 120%; border-radius: 2px; background: #94a3b8; }
.darma-loader-darma-b16-canal-lock-fill .darma-loader-darma-b16-canal-lock-fill__gate { position: absolute; top: 6%; bottom: 6%; width: 10%; border-radius: 3px; background: linear-gradient(#64748b, #1e293b); }
.darma-loader-darma-b16-canal-lock-fill .darma-loader-darma-b16-canal-lock-fill__gate:nth-of-type(2) { left: 3%; }
.darma-loader-darma-b16-canal-lock-fill .darma-loader-darma-b16-canal-lock-fill__gate:nth-of-type(3) { right: 3%; animation: darma-loader-darma-b16-canal-lock-fill-lock-gate calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b16-canal-lock-fill-lock-fill { 0%, 8% { height: 16%; } 56%, 78% { height: 84%; } 96%, 100% { height: 16%; } }
@keyframes darma-loader-darma-b16-canal-lock-fill-lock-lift { 0%, 8% { bottom: 12%; } 56%, 78% { bottom: 78%; } 96%, 100% { bottom: 12%; } }
@keyframes darma-loader-darma-b16-canal-lock-fill-lock-gate { 0%, 74% { transform: scaleY(1); opacity: 1; } 84%, 94% { transform: scaleY(.12); opacity: .5; } 100% { transform: scaleY(1); opacity: 1; } }

